using System.Diagnostics;
using System.Numerics;
using System.Text.Json;

namespace Laya.Tests;

/// <summary>
/// <see cref="PythonJsonReader"/> against CPython 3.12 <c>json.loads</c>, the warning repr of each JSON literal,
/// float parsing bit for bit, and the once-per-process warning filter. Every expectation below was produced by
/// running the Python reference (<c>json.loads</c>, <c>float</c>, <c>laya.common.clamp_temperature</c>,
/// <c>window_budget</c> under <c>warnings.simplefilter("always")</c>) on the same input; regenerate with the
/// scratch generator rather than editing by hand.
/// </summary>
public sealed class PythonJsonReaderTests
{
