    [Theory]
    [MemberData(nameof(Accepts))]
    public void AcceptsAndRejectsExactlyWhenPythonDoes(string text, string? repr, bool accepted)
    {
        if (!accepted)
        {
            Assert.ThrowsAny<JsonException>(() => PythonJsonReader.Parse(text));
            return;
        }
        var value = PythonJsonReader.Parse(text);
        if (repr is not null) Assert.Equal(repr, PythonFloat.Repr(value));
    }

