    [Theory]
    [MemberData(nameof(Floats))]
    public void FloatLiteralsAreBitIdenticalToPythonAndReprTheSame(string literal, long bits, string repr)
    {
        var value = Assert.IsType<double>(PythonJsonReader.Parse(literal));
        Assert.Equal(bits, BitConverter.DoubleToInt64Bits(value));
        Assert.Equal(repr, PythonFloat.Repr(value));
    }

    [Theory]
    [InlineData("-0", 0.5, "temperature[0]=0 -> 0.5")]
    [InlineData("0", 0.5, "temperature[0]=0 -> 0.5")]
    [InlineData("7", 5.0, "temperature[0]=7 -> 5")]
    [InlineData("7.0", 5.0, "temperature[0]=7.0 -> 5")]
    [InlineData("-0.0", 0.5, "temperature[0]=-0.0 -> 0.5")]
    [InlineData("1", 1.0, "")]
    [InlineData("1.0", 1.0, "")]
    [InlineData("2.5", 2.5, "")]
    [InlineData("100000000000000000000000000000", 5.0, "temperature[0]=100000000000000000000000000000 -> 5")]
    [InlineData("-100000000000000000000000000000", 0.5, "temperature[0]=-100000000000000000000000000000 -> 0.5")]
    [InlineData("", 5.0, "temperature[0] -> 5")]
    [InlineData("1e400", 1.0, "temperature[0]=inf -> 1")]
    [InlineData("-1e400", 1.0, "temperature[0]=-inf -> 1")]
    [InlineData("0.1006", 0.5, "temperature[0]=0.1006 -> 0.5")]
    [InlineData("1E2", 5.0, "temperature[0]=100.0 -> 5")]
    [InlineData("5e0", 5.0, "")]
    [InlineData("0.5", 0.5, "")]
    [InlineData("10", 5.0, "temperature[0]=10 -> 5")]
    [InlineData("100000000000000000000.0", 5.0, "temperature[0]=1e+20 -> 5")]
    [InlineData("1e22", 5.0, "temperature[0]=1e+22 -> 5")]
    [InlineData("1e-7", 0.5, "temperature[0]=1e-07 -> 0.5")]
    [InlineData("true", 1.0, "temperature[0]=True -> 1")]
    [InlineData("null", 1.0, "temperature[0]=None -> 1")]
    [InlineData("\"2.5\"", 2.5, "")]
    [InlineData("\"x\"", 1.0, "temperature[0]='x' -> 1")]
    [InlineData("[1]", 1.0, "temperature[0]=[1] -> 1")]
    [InlineData("NaN", 1.0, "temperature[0]=nan -> 1")]
    [InlineData("Infinity", 1.0, "temperature[0]=inf -> 1")]
    [InlineData("-Infinity", 1.0, "temperature[0]=-inf -> 1")]
    public void WarningEntryUsesTheLiteralsPythonType(string literal, double applied, string entry)
    {
        // Distinct text per row is not needed: the entry list is on the config, the trace is deduplicated separately.
        var config = LayaConfig.Parse("{\"temperature\": [" + literal + ", 1, 1]}");
        Assert.Equal(applied, config.Temperature[0]);
        Assert.Equal<IEnumerable<string>>(entry.Length == 0 ? [] : new[] { entry }, config.ClampedTemperatures);
    }

    [Fact]
    public void ARealStringIsNeverReadAsNaNOrInfinity()
    {
        var config = LayaConfig.Parse("{\"temperature\": [\"NaN\", \"Infinity\", \"\\uE000laya-nan\"], \"encoder\": \"NaN\"}");
        Assert.Equal("NaN", config.Encoder);
        Assert.Equal(["temperature[0]='NaN' -> 1", "temperature[1]='Infinity' -> 1", "temperature[2]='\\ue000laya-nan' -> 1"], config.ClampedTemperatures);
    }

    [Fact]
    public void ConfigRejectsMalformedJsonAsPythonDoes()
    {
        foreach (var bad in new[] { "{NaN: 1}", "{\"temperature\": [nan]}", "{\"temperature\": [1,]}", "{\"temperature\": [01]}", "{'a': 1}" })
            Assert.ThrowsAny<JsonException>(() => LayaConfig.Parse(bad));
        Assert.Throws<InvalidDataException>(() => LayaConfig.Parse("[1]"));
    }

    [Fact]
    public void IntegerLiteralsKeepPythonsIntTypeAndFloatLiteralsStayFloats()
    {
        Assert.IsType<long>(PythonJsonReader.Parse("7"));
        Assert.IsType<long>(PythonJsonReader.Parse("-0"));
        Assert.IsType<BigInteger>(PythonJsonReader.Parse("9223372036854775808"));
        Assert.IsType<double>(PythonJsonReader.Parse("7.0"));
        Assert.IsType<double>(PythonJsonReader.Parse("7e0"));
    }
}

/// <summary>
/// Classes that observe or reset the process-wide warning state (<see cref="WarnOnce"/>, <c>Trace.Listeners</c>) share
/// this collection, and it never runs in parallel: xunit runs it alone, so no other class warns or resets meanwhile.
/// </summary>
[CollectionDefinition(Name, DisableParallelization = true)]
public sealed class WarningStateCollection
{
    /// <summary>The collection name.</summary>
    public const string Name = "warning-state";
}

/// <summary>Python's default warnings filter: one trace per distinct (site, text) per process.</summary>
[Collection(WarningStateCollection.Name)]
public sealed class WarnOnceTests
{
    private sealed class Capture : TraceListener
    {
        private readonly object _gate = new();
        private readonly List<string> _messages = [];
        private readonly int? _thread;
        public Capture(int? onlyThread) => _thread = onlyThread;
        public List<string> Messages { get { lock (_gate) return [.. _messages]; } }
        public override void Write(string? message) { lock (_gate) _messages.Add(message ?? ""); }
        public override void WriteLine(string? message) { lock (_gate) _messages.Add(message ?? ""); }
        public override void TraceEvent(TraceEventCache? eventCache, string source, TraceEventType eventType, int id, string? format, params object?[]? args)
        {
            // Other test classes warn from their own threads and call sites; only the ones raised here count.
            if (_thread is { } thread && Environment.CurrentManagedThreadId != thread) return;
            lock (_gate) _messages.Add(args is null ? format ?? "" : string.Format(format ?? "", args));
        }
    }

    private static List<string> Capturing(Action action, string needle = "laya", bool anyThread = false)
    {
        var capture = new Capture(anyThread ? null : Environment.CurrentManagedThreadId);
        Trace.Listeners.Add(capture);
        try { action(); }
        finally { Trace.Listeners.Remove(capture); }
        return capture.Messages.Where(m => m.StartsWith("laya", StringComparison.Ordinal) && m.Contains(needle)).ToList();
    }

    private const string Config = "{\"temperature\": [0.2, 1, 1]}";

    // ── call sites (Python keys the default filter on the frame stacklevel selects) ──

    private static string TempConfig(string value) => "{\"temperature\": [" + value + ", 1, 1]}";

    [Fact]
    public void TheSameCallSiteInALoopWarnsOnce()
    {
        WarnOnce.Reset();
        var messages = Capturing(() => { for (var i = 0; i < 5; i++) LayaConfig.Parse(Config); }, "temperature[0]=0.2 ");
        Assert.Single(messages);
        Assert.StartsWith("laya ONNX: this checkpoint ships temperatures outside [0.5, 5]", messages[0]);
    }

    [Fact]
    public void TwoCallSitesWarnTwiceForTheSameText()
    {
        WarnOnce.Reset();
        var messages = Capturing(() =>
        {
            LayaConfig.Parse(Config);
            LayaConfig.Parse(Config);
        }, "temperature[0]=0.2 ");
        Assert.Equal(2, messages.Count);
    }

    [Fact]
    public void ANewTextFromTheSameSiteWarnsAgain()
    {
        WarnOnce.Reset();
        var messages = Capturing(() =>
        {
            foreach (var value in new[] { "0.3", "0.3", "0.4" }) LayaConfig.Parse(TempConfig(value));
        }, "temperature[0]=0.");
        Assert.Equal(2, messages.Count(m => m.Contains("temperature[0]=0.3 ")) + messages.Count(m => m.Contains("temperature[0]=0.4 ")));
        Assert.Single(messages, m => m.Contains("temperature[0]=0.3 "));
    }

    // A public entry is attributed to its caller, and overloads that call each other are one entry.
    [WarnSite, System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
    private static void EntryOverload(string text) => EntryCore(text);

    [WarnSite, System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
    private static void EntryCore(string text) => WarnOnce.Warn(text);

    [Fact]
    public void AnEntryIsKeyedByItsCallerNotByTheLibraryLine()
    {
        WarnOnce.Reset();
        var once = Capturing(() => { for (var i = 0; i < 4; i++) EntryOverload("laya: site test loop"); }, "site test loop");
        Assert.Single(once);
        var twice = Capturing(() =>
        {
            EntryOverload("laya: site test lines");
            EntryOverload("laya: site test lines");
        }, "site test lines");
        Assert.Equal(2, twice.Count);
    }

    // Through the router the site is the router's own call into the checkpoint, as Python attributes it to router.py.
    private sealed class WarningScanner : ILayaPredictor, ILayaLongPredictor
    {
        public LayaResult Predict(object? state, QuestionSet questions) => throw new NotSupportedException();

        [WarnSite, System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
        public LayaResult PredictLong(object state, QuestionSet questions, int? window = null, int? stride = null,
                                      string aggregate = "auto", int? batchSize = null)
        {
            WarnOnce.Warn("laya: predict_long: via the router");
            return new LayaResult("scanner", [], new Dictionary<string, Answer>(StringComparer.Ordinal), new Usage(0, 0));
        }
    }

    [Fact]
    public void CallsThroughTheRouterFromDifferentUserLinesWarnOnce()
    {
        WarnOnce.Reset();
        using var router = new LayaRouter(new LayaRouterOptions(), _ => new WarningScanner());
        var messages = Capturing(() =>
        {
            router.PredictLong("hello", new QuestionSet());
            router.PredictLong("hello again", new QuestionSet());
        }, "via the router");
        Assert.Single(messages);
    }

    // One un-optimized call site shared by every thread: a jitted-and-re-jitted lambda may report a different IL offset.
    [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining | System.Runtime.CompilerServices.MethodImplOptions.NoOptimization)]
    private static void LoadFromOneSite() => LayaConfig.Parse(TempConfig("0.25"));

    // xunit runs other classes (ConfigFieldTypeTests) in parallel and they warn about temperature[0]=0.2 from their
    // own threads while this listener is attached, so this test counts only a value no other test uses, and a
    // foreign warning from another thread is raised on purpose to prove it is not counted.
    [Fact]
    public void ConcurrentLoadsWarnOnce()
    {
        WarnOnce.Reset();
        var messages = Capturing(() =>
        {
            var foreign = Task.Run(() => LayaConfig.Parse("{\"temperature\": [0.2, 1, 1], \"temperature_by_options\": {\"x\": 9}}"));
            Parallel.For(0, 32, _ => LoadFromOneSite());
            foreign.Wait();
        }, "temperature[0]=0.25 ", anyThread: true);
        Assert.Single(messages);
    }

    public static TheoryData<int, int, int, int?, int?, string, string[]> Scenarios() => new()
    {
        { 100, 512, 192, 1000, null, "100,50,100", new string[] { "laya: predict_long: window=1000 is wider than the 100 state tokens these questions leave inside max_len=512, so every window would be truncated to 100 on the way to the model; scanning with window=100 instead" } },
        { 100, 512, 192, null, null, "100,50,100", new string[] { "laya: predict_long: these questions leave only 100 of max_len=512 for the state (their heads take the rest), so the scan window is capped 312 -> 100 and roughly 3.1x as many windows -- each a full forward pass -- are needed to read the document. Fewer or shorter options, a larger max_len, or laya.shortlist.predict_shortlist for a large label set will all cost less than scanning at this width" } },
        { 24, 174, 100, null, null, "24,12,24", new string[] { "laya: predict_long: these questions leave only 24 of max_len=174 for the state (their heads take the rest), so the scan window is capped 66 -> 24 and roughly 2.8x as many windows -- each a full forward pass -- are needed to read the document. Fewer or shorter options, a larger max_len, or laya.shortlist.predict_shortlist for a large label set will all cost less than scanning at this width" } },
        { 32, 180, 100, null, null, "32,16,32", new string[] { "laya: predict_long: these questions leave only 32 of max_len=180 for the state (their heads take the rest), so the scan window is capped 72 -> 32 and roughly 2.2x as many windows -- each a full forward pass -- are needed to read the document. Fewer or shorter options, a larger max_len, or laya.shortlist.predict_shortlist for a large label set will all cost less than scanning at this width" } },
        { 100, 512, 192, 1000, 500, "100,50,100", new string[] { "laya: predict_long: window=1000 is wider than the 100 state tokens these questions leave inside max_len=512, so every window would be truncated to 100 on the way to the model; scanning with window=100 instead", "laya: predict_long: stride=500 was a 50% step for the window=1000 you asked for, but the window was reduced to 100 to fit the room these questions leave; scanning with stride=50 instead" } },
        { 200, 512, 192, null, null, "200,100,200", new string[] {  } },
        { 100, 512, 192, 500, 400, "100,50,100", new string[] { "laya: predict_long: window=500 is wider than the 100 state tokens these questions leave inside max_len=512, so every window would be truncated to 100 on the way to the model; scanning with window=100 instead", "laya: predict_long: stride=400 was a 50% step for the window=500 you asked for, but the window was reduced to 100 to fit the room these questions leave; scanning with stride=50 instead" } },
        { 150, 512, 192, null, null, "150,75,150", new string[] { "laya: predict_long: these questions leave only 150 of max_len=512 for the state (their heads take the rest), so the scan window is capped 312 -> 150 and roughly 2.1x as many windows -- each a full forward pass -- are needed to read the document. Fewer or shorter options, a larger max_len, or laya.shortlist.predict_shortlist for a large label set will all cost less than scanning at this width" } },
        { 104, 512, 192, null, null, "104,52,104", new string[] { "laya: predict_long: these questions leave only 104 of max_len=512 for the state (their heads take the rest), so the scan window is capped 312 -> 104 and roughly 3.0x as many windows -- each a full forward pass -- are needed to read the document. Fewer or shorter options, a larger max_len, or laya.shortlist.predict_shortlist for a large label set will all cost less than scanning at this width" } },
        { 399, 512, 192, 400, 399, "399,399,399", new string[] { "laya: predict_long: window=400 is wider than the 399 state tokens these questions leave inside max_len=512, so every window would be truncated to 399 on the way to the model; scanning with window=399 instead" } },
        { 100, 512, 192, 1000, 2000, "ERR", new string[] { "laya: predict_long: window=1000 is wider than the 100 state tokens these questions leave inside max_len=512, so every window would be truncated to 100 on the way to the model; scanning with window=100 instead" } },
    };

    [Theory]
    [MemberData(nameof(Scenarios))]
    public void PredictLongWarningsHavePythonsTextAndAreShownOnce(int room, int maxLen, int head, int? window, int? stride, string result, string[] expected)
    {
        var requested = window is > 0 ? window.Value : Math.Max(64, maxLen - head - 8);
        WarnOnce.Reset();
        (int, int, int) got = default;
        var threw = false;
        void Run() { try { var b = LongPrediction.BudgetForRoom(requested, room, maxLen, head, window, stride); got = (b.Window, b.Stride, b.Room); } catch (ArgumentException) { threw = true; } }
        var first = Capturing(Run);
        Assert.Equal(result == "ERR", threw);
        if (!threw) Assert.Equal(result, $"{got.Item1},{got.Item2},{got.Item3}");
        Assert.Equal(expected, first.Where(m => m.StartsWith("laya: predict_long")).ToArray());
        var second = Capturing(Run);
        Assert.DoesNotContain(second, m => m.StartsWith("laya: predict_long"));
    }
}

/// <summary>
/// Config files are read like Python's <c>json.load(open(path))</c>: strict UTF-8, a BOM is an error
/// (<c>json.loads</c>: "Unexpected UTF-8 BOM (decode using utf-8-sig)"), invalid bytes are an error.
/// Checked against CPython 3.12 reading the same bytes with <c>encoding="utf-8"</c>.
/// </summary>
public sealed class ConfigFileEncodingTests
{
    private static string Write(byte[] bytes)
    {
        var path = Path.Combine(Path.GetTempPath(), "laya-cfg-" + Guid.NewGuid().ToString("N") + ".json");
        File.WriteAllBytes(path, bytes);
        return path;
    }

    private static readonly byte[] Bom = [0xEF, 0xBB, 0xBF];

    [Fact]
    public void AValidUtf8FileLoads()
    {
        var path = Write("{\"encoder\": \"café\", \"max_len\": 64}"u8.ToArray());
        try { Assert.Equal("café", LayaConfig.Load(path).Encoder); }
        finally { File.Delete(path); }
    }

    [Fact]
    public void ABomIsRejectedLikePython()
    {
        var path = Write([.. Bom, .. "{\"max_len\": 64}"u8.ToArray()]);
        try { Assert.Contains("Unexpected UTF-8 BOM", Assert.Throws<JsonException>(() => LayaConfig.Load(path)).Message); }
        finally { File.Delete(path); }
    }

    [Fact]
    public void InvalidUtf8IsRejectedLikePython()
    {
